import chess,time,sys
V=[0,100,320,335,500,950,0]
# Values are from White's point of view, with a mild center/development preference.
PST={}
for c in [False,True]:
 for p in range(1,7):
  for s in range(64):
   f=chess.square_file(s);r=chess.square_rank(s) if c else 7-chess.square_rank(s)
   center=3.5-(abs(f-3.5)+abs(r-3.5))/2
   if p==1: v=r*6 + (3.5-abs(f-3.5))*4 + (12 if r>=4 else 0)
   elif p==2: v=center*17-(12 if r==0 else 0)
   elif p==3: v=center*9 + (6 if r>0 else -10)
   elif p==4: v=(18 if r==6 else 0)+(4 if f in (3,4) else 0)
   elif p==5:v=center*3
   else:v= -(r*12) + (12 if r==0 and f in (1,2,6) else 0)
   PST[c,p,s]=int((V[p]+v)*(1 if c else -1))
TT={};N=0;Q=0;start=0;limit=0;killers={};history={}
class Timeout(Exception):pass

def score(b):return sum(PST[p.color,p.piece_type,s] for s,p in b.piece_map().items())
def delta(b,m):
 p=b.piece_at(m.from_square);d=PST[p.color,m.promotion or p.piece_type,m.to_square]-PST[p.color,p.piece_type,m.from_square]
 cap=b.piece_at(m.to_square)
 if cap:d-=PST[cap.color,cap.piece_type,m.to_square]
 elif b.is_en_passant(m):d-=PST[not p.color,1,m.to_square-8 if p.color else m.to_square+8]
 if b.is_castling(m):
  rf=m.from_square+3 if m.to_square>m.from_square else m.from_square-4
  rt=m.from_square+1 if m.to_square>m.from_square else m.from_square-1
  d+=PST[p.color,4,rt]-PST[p.color,4,rf]
 return d

def order(b,m,tt,ply):
 if m==tt:return 10000000
 cap=b.piece_type_at(m.to_square)
 if cap or b.is_en_passant(m):return 100000+V[cap or 1]*10-V[b.piece_type_at(m.from_square)]
 if m.promotion:return 90000+V[m.promotion]
 if m in killers.get(ply,[]):return 80000
 return history.get((b.turn,m.from_square,m.to_square),0)

def qs(b,a,z,sc,ply,left=10):
 global N,Q
 N+=1;Q+=1
 if N%2048==0 and time.time()>limit:raise Timeout
 check=b.is_check();ev=sc if b.turn else -sc
 if left<=0:return ev
 if not check:
  if ev>=z:return ev
  if ev>a:a=ev
 moves=list(b.legal_moves if check else b.generate_legal_captures())
 if not moves and check:return -30000+ply
 moves.sort(key=lambda m:order(b,m,None,ply),reverse=True)
 for m in moves:
  if not check and not m.promotion:
   cap=b.piece_type_at(m.to_square) or 1
   if ev+V[cap]+200<a:continue
  d=delta(b,m);b.push(m)
  v=-qs(b,-z,-a,sc+d,ply+1,left-1)
  b.pop()
  if v>=z:return v
  if v>a:a=v
 return a

def search(b,depth,a,z,sc,ply,pv=False):
 global N
 N+=1
 if N%2048==0 and time.time()>limit:raise Timeout
 if b.halfmove_clock>=100 or (ply>0 and b.is_repetition(2)):return 0
 check=b.is_check()
 if depth<=0:return qs(b,a,z,sc,ply)
 key=b._transposition_key();entry=TT.get(key);tt=None;orig=a
 if entry:
  dd,v,fl,tt=entry
  if dd>=depth and not pv:
   if fl==0 or (fl==1 and v>=z) or (fl==2 and v<=a):return v
 moves=list(b.legal_moves)
 if not moves:return -30000+ply if check else 0
 moves.sort(key=lambda m:order(b,m,tt,ply),reverse=True)
 best=-31000;bm=None
 for i,m in enumerate(moves):
  quiet=not b.is_capture(m) and not m.promotion
  d=delta(b,m);b.push(m)
  if i==0:v=-search(b,depth-1,-z,-a,sc+d,ply+1,pv)
  else:
   reduction=1 if depth>=3 and i>=5 and quiet and not check and not b.is_check() else 0
   v=-search(b,depth-1-reduction,-a-1,-a,sc+d,ply+1)
   if reduction and v>a:v=-search(b,depth-1,-a-1,-a,sc+d,ply+1)
   if a<v<z:v=-search(b,depth-1,-z,-a,sc+d,ply+1,pv)
  b.pop()
  if v>best:best=v;bm=m
  if v>a:a=v
  if a>=z:
   if quiet:
    ks=killers.setdefault(ply,[])
    if m not in ks:ks.insert(0,m);del ks[2:]
    h=(b.turn,m.from_square,m.to_square);history[h]=history.get(h,0)+depth*depth
   break
 flag=2 if best<=orig else 1 if best>=z else 0
 TT[key]=(depth,best,flag,bm)
 return best

def pvline(b,maxlen=15):
 b=b.copy();line=[]
 for _ in range(maxlen):
  ent=TT.get(b._transposition_key())
  if not ent or not ent[3] or ent[3] not in b.legal_moves:break
  m=ent[3];line.append(b.san(m));b.push(m)
 return ' '.join(line)
if __name__=='__main__':
 b=chess.Board(sys.argv[1]);secs=int(sys.argv[2]) if len(sys.argv)>2 else 60
 start=time.time();limit=start+secs;sc=score(b)
 for dep in range(1,15):
  try:
   ev=search(b,dep,-31000,31000,sc,0,True)
   print(dep,ev,'nodes',N,'time',round(time.time()-start,1),pvline(b),flush=True)
  except Timeout:break
